6441	export class AccessorOp extends Operator<AccessorOp> {
6442	  static displayName = 'Accessor'
6443	  static description =
6444	    'A function called for each row of your data and passed to Deck.gl layer properties. The current row is passed as the `d` variable (e.g., `d.population`, `d.properties.color`). Available variables: `d` (current row), `i` (index), `data` (all rows), `op()` (access operators), `sequenceTime` (timeline position), `frame` (current frame), `totalFrames`, `sequence` (timeline metadata). Includes d3, turf, and other utilities.'
6445	  createInputs() {
6446	    return {
6447	      expression: new ExpressionField(),
6448	    }
6449	  }
6450	  createOutputs() {
6451	    return {
6452	      accessor: new FunctionField(),
6453	    }
6454	  }
6455	  execute({ expression }: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> {
6456	    const fn = fnWithSource(
6457	      [
6458	        'd',
6459	        'i',
6460	        'data',
6461	        'op',
6462	        'sequenceTime',
6463	        'frame',
6464	        'totalFrames',
6465	        'sequence',
6466	        ...Object.keys(freeExports),
6467	      ],
6468	      `return ${expression}`,
6469	      this.id
6470	    )
6471	
6472	    // Subscribe to timeline changes - accessor will get fresh values on each call
6473	    subscribeOpToTimeline(this)
6474	
6475	    // https://deck.gl/docs/developer-guide/using-layers#accessors
6476	    const accessor = (d: unknown, dInfo: { index: number; data: unknown; target: number[] }) => {
6477	      const contextualGetOp = safeOpGetter(this.id)
6478	      // Get fresh timeline values for each accessor call
6479	      const timelineContext = getTimelineContext()
6480	      try {
6481	        return fn(
6482	          d,
6483	          dInfo.index,
6484	          dInfo.data,
6485	          contextualGetOp,
6486	          timelineContext.sequenceTime,
6487	          timelineContext.frame,
6488	          timelineContext.totalFrames,
6489	          timelineContext.sequence,
6490	          ...Object.values(freeExports)
6491	        )
6492	      } catch (_e) {
6493	        // Swallow per-row errors — returning undefined lets deck.gl skip the item
6494	        // rather than crashing the GPU process
6495	        return undefined
6496	      }
6497	    }
6498	
6499	    return { accessor }
6500	  }
6501	}
6502	
6503	export class CodeOp extends Operator<CodeOp> {
6504	  static displayName = 'Code'
6505	  static description =
6506	    'Run custom JavaScript code to transform your data. Available variables: `data` (all input data), `d` (first element), `op()` (access other operators), `sequenceTime` (timeline position), `frame` (current frame), `totalFrames`, `sequence` (timeline metadata). Includes d3, turf, and other utilities. Use `this` to store state between executions.'
6507	  static supportsCustomFields = true
6508	  asDownload = () => this.outputs.data.value
6509	  createInputs() {
6510	    return {
6511	      data: new ListField(new DataField()),
6512	      code: new CodeField('', { language: 'javascript' }),
6513	    }
6514	  }
6515	  createOutputs() {
6516	    return {
6517	      data: new DataField(),
6518	    }
6519	  }
6520	  async execute({
6521	    data,
6522	    code: codeString,
6523	  }: ExtractProps<typeof this.inputs>): Promise<ExtractProps<typeof this.outputs>> {
6524	    // Replace self-parameter shorthand {{par.field}} with op() calls referencing this operator
6525	    let processedCode = codeString
6526	      .trim()
6527	      .replace(selfParMustacheRe, (_match, _inOut, fieldPath) => {
6528	        return `op('${this.id}').par.${fieldPath}`
6529	      })
6530	
6531	    // Replace standard mustache references with op() calls, handling relative paths
6532	    processedCode = processedCode.replace(mustacheRe, (_match, opId, inOut, fieldPath) => {
6533	      return `op('${opId}').${inOut}.${fieldPath}`
6534	    })
6535	
6536	    // Get current timeline values
6537	    const timelineContext = getTimelineContext()
6538	
6539	    // Subscribe to timeline changes for reactive updates
6540	    subscribeOpToTimeline(this)
6541	
6542	    // Create a context-aware getOp function for the code execution
6543	    const contextualGetOp = safeOpGetter(this.id)
6544	    const fn = fnWithSource(
6545	      [
6546	        'data',
6547	        'd',
6548	        'op',
6549	        'sequenceTime',
6550	        'frame',
6551	        'totalFrames',
6552	        'sequence',
6553	        ...Object.keys(freeExports),
6554	      ],
6555	      processedCode,
6556	      this.id
6557	    )
6558	    const result = fn.call(
6559	      this,
6560	      data,
6561	      data[0],
6562	      contextualGetOp,
6563	      timelineContext.sequenceTime,
6564	      timelineContext.frame,
6565	      timelineContext.totalFrames,
6566	      timelineContext.sequence,
6567	      ...Object.values(freeExports)
6568	    )
6569	
6570	    const output = result instanceof Promise ? await result : result
6571	    return { data: output }
6572	  }
6573	}
6574	
6575	export class ContainerOp extends Operator<ContainerOp> {
6576	  static displayName = 'Container'
6577	  static description = 'Encapsulates a subgraph of operators. Visually groups child nodes.'
6578	  static supportsCustomFields = true
6579	
6580	  createInputs() {
6581	    return { in: new UnknownField(null, { optional: true }) }
6582	  }
6583	
6584	  createOutputs() {
6585	    return { out: new UnknownField(null, { optional: true }) }
6586	  }
6587	
6588	  execute(_: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> {
6589	    let outputValue = null
6590	    // The 'in' port of ContainerOp drives its execution.
6591	    // The 'out' port should reflect the value from a GraphOutputOp inside it.
6592	    for (const op of getAllOps()) {
6593	      if (op instanceof GraphOutputOp && isDirectChild(op.id, this.id)) {
6594	        outputValue = op.outputs.propagatedValue.value
6595	        break // Take the first one found
6596	      }
6597	    }
6598	    return { out: outputValue }
6599	  }
6600	}
6601	
6602	export class ExpressionOp extends Operator<ExpressionOp> {
6603	  static displayName = 'Expression'
6604	  static description =
6605	    'Evaluate a JavaScript expression to compute a single value. Available variables: `data` (all input data), `d` (first element), `op()` (access other operators), `sequenceTime` (timeline position), `frame` (current frame), `totalFrames`, `sequence` (timeline metadata). Includes d3, turf, and other utilities.'
6606	  createInputs() {
6607	    return {
6608	      data: new ListField(new DataField()),
6609	      expression: new ExpressionField(),
6610	    }
6611	  }
6612	  createOutputs() {
6613	    return {
6614	      data: new DataField(),
6615	    }
6616	  }
6617	  execute({
6618	    data,
6619	    expression,
6620	  }: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> {
6621	    // Get current timeline values
6622	    const timelineContext = getTimelineContext()
6623	
6624	    // Subscribe to timeline changes for reactive updates
6625	    subscribeOpToTimeline(this)
6626	
6627	    const fn = fnWithSource(
6628	      [
6629	        'data',
6630	        'd',
6631	        'op',
6632	        'sequenceTime',
6633	        'frame',
6634	        'totalFrames',
6635	        'sequence',
6636	        ...Object.keys(freeExports),
6637	      ],
6638	      `return ${expression}`,
6639	      this.id
6640	    )

965	export class NumberOp extends Operator<NumberOp> {
966	  static displayName = 'Number'
967	  static description = 'A number'
