983	export class MapRangeOp extends Operator<MapRangeOp> {
984	  static displayName = 'MapRange'
985	  static description =
986	    'Remap a number from one range to another (e.g., map 0-100 to 0-1, or temperature to color intensity)'
987	  public createInputs() {
988	    return {
989	      val: new NumberField(0, { step: 0.01, accessor: true }),
990	      inMin: new NumberField(0, { step: 0.1 }),
991	      inMax: new NumberField(1, { step: 0.1 }),
992	      outMin: new NumberField(0, { step: 0.1 }),
993	      outMax: new NumberField(1, { step: 0.1 }),
994	    }
995	  }
996	  public createOutputs() {
997	    return {
998	      scaled: new NumberField(),
999	    }
1000	  }
1001	  execute({
1002	    val,
1003	    inMin,
1004	    inMax,
1005	    outMin,
1006	    outMax,
1007	  }: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> {
1008	    const scale = scaleLinear().domain([inMin, inMax]).range([outMin, outMax])
1009	    // Use composeAccessor helper to handle both static values and accessor functions
1010	    const scaled = composeAccessor(val, (v: number) => scale(v))
1011	    return { scaled }
1012	  }
1013	}
