1015	export class ExtentOp extends Operator<ExtentOp> {
1016	  static displayName = 'Extent'
1017	  static description =
1018	    'Find the minimum and maximum values in your data (e.g., to set color scale ranges or determine data bounds)'
1019	  createInputs() {
1020	    return {
1021	      data: new DataField(),
1022	      accessor: new UnknownField((d: unknown) => d, { accessor: true, optional: true }),
1023	    }
