4086	export class GraphInputOp extends Operator<GraphInputOp> {
4087	  static displayName = 'GraphInput'
4088	  static description = 'Receives input from the parent Container.'
4089	  private _containerSub: Subscription | null = null
4090	
4091	  createInputs() {
4092	    return { parentValue: new UnknownField(null, { optional: true }) }
4093	  }
4094	
4095	  createOutputs() {
4096	    return { value: new UnknownField(null, { optional: true }) }
4097	  }
4098	
4099	  execute(inputs: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> {
4100	    const result: Record<string, unknown> = { value: inputs.parentValue }
4101	    // Pass through all custom field values from inputs to outputs
4102	    for (const key of Object.keys(this.outputs)) {
4103	      if (key !== 'value' && key in inputs) {
4104	        result[key] = inputs[key]
4105	      }
4106	    }
4107	    return result as ExtractProps<typeof this.outputs>
4108	  }
4109	
4110	  /**
4111	   * Set the parent ContainerOp and subscribe to custom field changes.
4112	   * When container custom fields change, rebuild outputs to mirror them.
4113	   */
4114	  setParentContainer(containerOp: ContainerOp | null) {
4115	    // Unsubscribe from previous container
4116	    if (this._containerSub) {
4117	      this._containerSub.unsubscribe()
4118	      this._containerSub = null
4119	    }
4120	
4121	    if (containerOp) {
4122	      // Initial sync
4123	      this.rebuildFromContainer(containerOp)
4124	
4125	      // Subscribe to future changes
4126	      this._containerSub = containerOp.customFieldsChanged.subscribe(() => {
4127	        this.rebuildFromContainer(containerOp)
4128	      })
4129	    }
4130	  }
4131	
4132	  /**
4133	   * Rebuild both inputs and outputs to mirror the parent ContainerOp's custom input fields.
4134	   * Creates an input and output for each custom field on the container.
4135	   * This allows values to flow: container input → GraphInputOp input → execute() → GraphInputOp output
4136	   */
4137	  rebuildFromContainer(containerOp: ContainerOp) {
4138	    // Preserve old values where possible
4139	    const oldInputValues = new Map<string, unknown>()
4140	    for (const [name, field] of Object.entries(this.inputs)) {
4141	      oldInputValues.set(name, field.value)
4142	    }
4143	    const oldOutputValues = new Map<string, unknown>()
4144	    for (const [name, field] of Object.entries(this.outputs)) {
4145	      oldOutputValues.set(name, field.value)
4146	    }
4147	
4148	    // Rebuild inputs: parentValue + custom fields
4149	    const newInputs: Record<string, Field> = {
4150	      parentValue: new UnknownField(null, { optional: true }),
4151	    }
4152	    for (const def of containerOp.customInputDefinitions) {
4153	      const field = this.createFieldFromDefinition(def)
4154	      newInputs[def.name] = field
4155	    }
4156	    this.inputs = newInputs as ReturnType<GraphInputOp['createInputs']>
4157	
4158	    // Rebuild outputs: value + custom fields
4159	    const newOutputs: Record<string, Field> = {
4160	      value: new UnknownField(null, { optional: true }),
4161	    }
4162	    for (const def of containerOp.customInputDefinitions) {
4163	      const field = this.createFieldFromDefinition(def)
4164	      newOutputs[def.name] = field
4165	    }
4166	    this.outputs = newOutputs as ReturnType<GraphInputOp['createOutputs']>
4167	
4168	    // Restore input values where field names match
4169	    for (const [name, field] of Object.entries(this.inputs)) {
4170	      if (oldInputValues.has(name)) {
4171	        try {
4172	          field.setValue(oldInputValues.get(name))
4173	        } catch (_err) {
4174	          // Type mismatch, skip
4175	        }
4176	      }
4177	    }
4178	
4179	    // Restore output values where field names match
4180	    for (const [name, field] of Object.entries(this.outputs)) {
4181	      if (oldOutputValues.has(name)) {
4182	        try {
4183	          field.setValue(oldOutputValues.get(name))
4184	        } catch (_err) {
4185	          // Type mismatch, skip
4186	        }
4187	      }
4188	    }
4189	
4190	    // Re-assign pathToProps for inputs
4191	    for (const [key, field] of Object.entries(this.inputs)) {
4192	      field.pathToProps = [this.id, IN_NS, key]
4193	      field.op = this
4194	    }
4195	
4196	    // Re-assign pathToProps for outputs
4197	    for (const [key, field] of Object.entries(this.outputs)) {
4198	      field.pathToProps = [this.id, OUT_NS, key]
4199	      field.op = this
4200	    }
4201	
4202	    // Notify that fields changed
4203	    this.markDirty()
4204	  }
4205	
4206	  dispose() {
4207	    if (this._containerSub) {
4208	      this._containerSub.unsubscribe()
4209	    }
4210	    super.dispose()
4211	  }
4212	}
